\question{9}{8}
\begin{subparts}
  \item It is given that the general term $a_n$ of a sequence is
  \[
    a_n = \dfrac{2n}{n+1}.
  \]
  Find the products of
  \begin{subpartsii}
    \item the first $4$ terms,
    \item the first $10$ terms.
  \end{subpartsii}
  Express the answers in index notation.

  \finishquestion\answerlines{6}

  \item It is given that the general term $b_n$ of another sequence is
  \[
    b_n = (-1)^n \times \dfrac{n}{n+1}.
  \]
  Using the result of (a)(ii), find the product of the first $10$ terms.
\end{subparts}

\answerlines{6}

% ============================================================
% ms-q9.tex - Marking scheme for Question 9 (8 marks)
% ============================================================

\msquestion{9}{8}

\[
a_n = \dfrac{2n}{n+1}, \qquad b_n = (-1)^n \times \dfrac{n}{n+1}.
\]

\vspace{4pt}

\begin{mspart}{(a)}
  \msstep{(i) \ \dfrac{2}{2} \times \dfrac{4}{3} \times \dfrac{6}{4} \times \dfrac{8}{5} = \dfrac{2^4}{5}}{1M}
  \msstep{\phantom{(i) \ }= \dfrac{16}{5}}{1A}
  \msstep{(ii) \ \dfrac{2 \times 4 \times 6 \times \cdots \times 20}{2 \times 3 \times 4 \times \cdots \times 11} = \dfrac{2^{10}}{11}}{1M+1A}
  \msstep{\phantom{(ii) \ }\text{or } \dfrac{2^{10} \times 10!}{11!} = \dfrac{2^{10}}{11}}{1M}
\end{mspart}

\begin{mspart}{(b)}
  \msstep{b_n = (-1)^n \times \dfrac{a_n}{2}}{1M}
  \msstep{\text{Product of the first 10 terms} = \dfrac{1}{2^{10}} \times (-1)^{1+2+\cdots+10} \times \dfrac{2^{10}}{11}}{1M}
  \msstep{= (-1)^{55} \times \dfrac{1}{11}}{1M}
  \msstep{= -\dfrac{1}{11}}{1A}
\end{mspart}

