  \msstep{= \dfrac{19}{6} \div \dfrac{3}{4} - \dfrac{3}{5} = \dfrac{19}{6} \times \dfrac{4}{3} - \dfrac{3}{5}}{1M}
  \msstep{= \dfrac{38}{9} - \dfrac{3}{5} = \dfrac{190}{45} - \dfrac{27}{45}}{1M}
  \msstep{= \dfrac{163}{45}}{1A}
