  \msstep{= -\dfrac{9}{4} + \dfrac{5}{6} \times 4 \times \dfrac{3}{7} - \dfrac{6}{5} + \dfrac{3}{10} = -\dfrac{9}{4} + \dfrac{10}{7} - \dfrac{6}{5} + \dfrac{3}{10}}{1M}
  \msstep{= -\dfrac{315}{140} + \dfrac{200}{140} - \dfrac{168}{140} + \dfrac{42}{140}}{1M}
